// Linear scans for comment-import.ts's marker regexes (A§12). Moss matched its markers with
// `\s*[A-Za-z0-9_,\-\s]+?\s*` around the id, three quantifiers over the same characters, so a marker opener followed
// by a run of spaces cost the cube of the run; COMMENT_WRAPPED_IMAGE also rescanned a line from every image start.
// These scans return what moss's regexes return (comment-markers.golden.test.ts holds them to the regexes); each
// character is read a bounded number of times.

/** JavaScript's `\s`. */
function isSpace(code: number): boolean {
  return (
    (code >= 0x09 && code <= 0x0d) ||
    code === 0x20 ||
    code === 0xa0 ||
    code === 0x1680 ||
    (code >= 0x2000 && code <= 0x200a) ||
    code === 0x2028 ||
    code === 0x2029 ||
    code === 0x202f ||
    code === 0x205f ||
    code === 0x3000 ||
    code === 0xfeff
  );
}

/** `[A-Za-z0-9_,\-\s]`, the characters a marker's id list may hold. */
function isIdChar(code: number): boolean {
  return (
    (code >= 0x30 && code <= 0x39) ||
    (code >= 0x41 && code <= 0x5a) ||
    (code >= 0x61 && code <= 0x7a) ||
    code === 0x5f ||
    code === 0x2c ||
    code === 0x2d ||
    isSpace(code)
  );
}

/** A line terminator, where `^`, `$` and `.` stop under the `m` flag. */
function isLineTerminator(code: number): boolean {
  return code === 0x0a || code === 0x0d || code === 0x2028 || code === 0x2029;
}

const isSpaceOrTab = (code: number): boolean => code === 0x20 || code === 0x09;

export type CommentMarkerKind = 'legacy-open' | 'legacy-close' | 'open' | 'close';

export interface CommentMarkerAt {
  kind: CommentMarkerKind;
  start: number;
  end: number;
  /** The regexes' `([A-Za-z0-9_,\-\s]+?)` capture (absent for `{%/c%}`). */
  ids?: string;
}

/**
 * The id capture of `\s*([A-Za-z0-9_,\-\s]+?)\s*` over the id characters text[from, to): the run trimmed of `\s`, or,
 * when the run is all `\s`, its last character (the leading `\s*` gives one back to the group).
 */
function idCapture(text: string, from: number, to: number): string {
  let start = from;
  while (start < to && isSpace(text.charCodeAt(start))) start++;
  if (start === to) return text.slice(to - 1, to);
  let end = to;
  while (isSpace(text.charCodeAt(end - 1))) end--;
  return text.slice(start, end);
}

/**
 * The marker starting at `at`, if any: `{%c:ids%}`, `{%/c%}`, `%%m:ids:start%%` or `%%m:ids:end%%`. The id run ends at
 * the first character outside `[A-Za-z0-9_,\-\s]`, so each marker's extent is fixed and is found in one pass.
 */
export function commentMarkerAt(text: string, at: number): CommentMarkerAt | null {
  if (text.startsWith('{%/c%}', at)) return { kind: 'legacy-close', start: at, end: at + 6 };
  const legacy = text.startsWith('{%c:', at);
  if (!legacy && !text.startsWith('%%m:', at)) return null;
  const from = at + 4;
  let to = from;
  while (to < text.length && isIdChar(text.charCodeAt(to))) to++;
  if (to === from) return null;
  if (legacy) {
    return text.startsWith('%}', to) ? { kind: 'legacy-open', start: at, end: to + 2, ids: idCapture(text, from, to) } : null;
  }
  if (text.startsWith(':start%%', to)) return { kind: 'open', start: at, end: to + 8, ids: idCapture(text, from, to) };
  if (text.startsWith(':end%%', to)) return { kind: 'close', start: at, end: to + 6, ids: idCapture(text, from, to) };
  return null;
}

const PREFIX: Record<CommentMarkerKind, string> = { 'legacy-open': '{%c:', 'legacy-close': '{%/c%}', open: '%%m:', close: '%%m:' };

/** Every non-overlapping marker of one kind, left to right, as a global regex for that kind finds them. */
function markersOfKind(text: string, kind: CommentMarkerKind): CommentMarkerAt[] {
  const found: CommentMarkerAt[] = [];
  let from = 0;
  for (;;) {
    const at = text.indexOf(PREFIX[kind], from);
    if (at < 0) return found;
    const marker = commentMarkerAt(text, at);
    if (marker && marker.kind === kind) {
      found.push(marker);
      from = marker.end;
    } else {
      from = at + 1;
    }
  }
}

export interface ScannedCommentMarker {
  type: 'open' | 'close';
  index: number;
  length: number;
  ids?: string[];
}

const splitIds = (ids: string): string[] => ids.split(',').map((id) => id.trim()).filter((id) => id.length > 0);

/** comment-import.ts's findMarkers: each kind's matches, merged by index. */
export function scanCommentMarkers(text: string): ScannedCommentMarker[] {
  const matches: ScannedCommentMarker[] = [];
  for (const kind of ['legacy-open', 'open'] as const) {
    for (const m of markersOfKind(text, kind)) matches.push({ type: 'open', index: m.start, length: m.end - m.start, ids: splitIds(m.ids as string) });
  }
  for (const kind of ['legacy-close', 'close'] as const) {
    for (const m of markersOfKind(text, kind)) matches.push({ type: 'close', index: m.start, length: m.end - m.start });
  }
  matches.sort((a, b) => a.index - b.index);
  return matches;
}

/** comment-import.ts's markerIdList: the ids of the first modern marker, else of the first legacy opener. */
export function commentMarkerIdList(marker: string): string | null {
  const first = (prefix: string, kinds: CommentMarkerKind[]): CommentMarkerAt | null => {
    for (let at = marker.indexOf(prefix); at >= 0; at = marker.indexOf(prefix, at + 1)) {
      const found = commentMarkerAt(marker, at);
      if (found && kinds.includes(found.kind)) return found;
    }
    return null;
  };
  const found = first('%%m:', ['open', 'close']) ?? first('{%c:', ['legacy-open']);
  return found ? (found.ids as string).split(',').map((id) => id.trim()).join(',') : null;
}

/**
 * comment-import.ts's normalizeCommentWrappedAtxHeadings, without its regex: on each line, an indent of up to three
 * spaces or tabs, an opening marker, one to six `#`, spaces or tabs, the heading, the first closing marker that only
 * spaces or tabs follow to the end of its line, become the heading with the opening marker after its spacing.
 */
export function scanCommentWrappedAtxHeadings(markdown: string): string {
  const length = markdown.length;
  let out = '';
  let last = 0;
  let line = 0;
  while (line < length) {
    const match = atxHeadingLineAt(markdown, line);
    if (match !== null) {
      out += markdown.slice(last, line) + match.replacement;
      last = match.end;
    }
    // The next line start after the match's end, or after this line.
    let next = match !== null ? match.end : line;
    while (next < length && !isLineTerminator(markdown.charCodeAt(next))) next++;
    line = next + 1;
  }
  return last === 0 ? markdown : out + markdown.slice(last);
}

function atxHeadingLineAt(text: string, line: number): { end: number; replacement: string } | null {
  let at = line;
  while (at < line + 3 && isSpaceOrTab(text.charCodeAt(at))) at++;
  const open = commentMarkerAt(text, at);
  if (!open || (open.kind !== 'open' && open.kind !== 'legacy-open')) return null;
  let hashes = open.end;
  while (text.charCodeAt(hashes) === 0x23) hashes++;
  if (hashes === open.end || hashes - open.end > 6) return null;
  let content = hashes;
  while (isSpaceOrTab(text.charCodeAt(content))) content++;
  if (content === hashes) return null;
  // `(.*?)` then the closing marker: the first marker start on the line from which a close and trailing blanks reach
  // the end of a line.
  for (let at2 = content; at2 < text.length; at2++) {
    const code = text.charCodeAt(at2);
    if (isLineTerminator(code)) return null;
    if (code !== 0x7b && code !== 0x25) continue;
    const close = commentMarkerAt(text, at2);
    if (!close || (close.kind !== 'close' && close.kind !== 'legacy-close')) continue;
    let tail = close.end;
    while (tail < text.length && isSpaceOrTab(text.charCodeAt(tail))) tail++;
    if (tail < text.length && !isLineTerminator(text.charCodeAt(tail))) continue;
    const s = (from: number, to: number): string => text.slice(from, to);
    return {
      end: tail,
      replacement: `${s(line, at)}${s(open.end, hashes)}${s(hashes, content)}${s(at, open.end)}${s(content, at2)}${s(at2, close.end)}${s(close.end, tail)}`,
    };
  }
  return null;
}

export type CommentWrappedImageReplacer = (
  match: string,
  open: string,
  pre: string,
  image: string,
  post: string,
  close: string | undefined,
  offset: number,
  full: string,
) => string;

/**
 * `segment.replace(COMMENT_WRAPPED_IMAGE, replacer)` from comment-import.ts, without the regex. A match is an opening
 * marker; the shortest run of characters that are neither a newline nor a marker start, then an image (`![alt](src)`
 * with at most one level of parentheses in src, or `![[ref]]`) starting within that run; then the characters up to
 * the next newline or marker start, which must be a marker: a closing one is consumed, an opening one ends the match
 * before it.
 */
export function replaceCommentWrappedImages(segment: string, replacer: CommentWrappedImageReplacer): string {
  if (!segment.includes('{%') && !segment.includes('%%m:')) return segment;
  const scan = new ImageScan(segment);
  let out = '';
  let last = 0;
  let from = 0;
  for (let index = scan.markerFrom(0); index < scan.markers.length; index = scan.markerFrom(from)) {
    const open = scan.markers[index];
    if (open.kind !== 'open' && open.kind !== 'legacy-open') {
      from = open.start + 1;
      continue;
    }
    const match = scan.matchAt(open);
    if (!match) {
      from = open.start + 1;
      continue;
    }
    const s = (a: number, b: number): string => segment.slice(a, b);
    out += s(last, open.start);
    out += replacer(
      s(open.start, match.end),
      s(open.start, open.end),
      s(open.end, match.image),
      s(match.image, match.imageEnd),
      s(match.imageEnd, match.post),
      match.close ? s(match.close.start, match.close.end) : undefined,
      open.start,
      segment,
    );
    last = match.end;
    from = match.end;
  }
  return last === 0 ? segment : out + segment.slice(last);
}

/** The first index in [0, count) whose ascending key is at least `from`, or `count`. */
function firstAtOrAfter(count: number, key: (index: number) => number, from: number): number {
  let low = 0;
  let high = count;
  while (low < high) {
    const mid = (low + high) >> 1;
    if (key(mid) < from) low = mid + 1;
    else high = mid;
  }
  return low;
}

class ImageScan {
  readonly markers: CommentMarkerAt[] = [];
  private readonly text: string;
  private readonly srcEnds = new Map<number, number>();
  private readonly positions = new Map<string, number[]>();

  constructor(text: string) {
    this.text = text;
    // Every marker start, in order (markers may overlap: `:start%%m:` ends one and starts the next).
    for (let at = 0; at < text.length; at++) {
      const code = text.charCodeAt(at);
      if (code !== 0x7b && code !== 0x25) continue;
      const marker = commentMarkerAt(text, at);
      if (marker) this.markers.push(marker);
    }
  }

  /** The index of the first marker starting at or after `from`. */
  markerFrom(from: number): number {
    return firstAtOrAfter(this.markers.length, (index) => this.markers[index].start, from);
  }

  /** The first index at or after `from` holding `char`, or the text's length. */
  private nextOf(char: string, from: number): number {
    let list = this.positions.get(char);
    if (!list) {
      list = [];
      for (let at = this.text.indexOf(char); at >= 0; at = this.text.indexOf(char, at + 1)) list.push(at);
      this.positions.set(char, list);
    }
    const found = list;
    const index = firstAtOrAfter(found.length, (i) => found[i], from);
    return index < found.length ? found[index] : this.text.length;
  }

  /** Where `[^\n]` stops being allowed for a non-marker run from `from`: the next newline or marker start. */
  private stopFrom(from: number): number {
    const index = this.markerFrom(from);
    const marker = index < this.markers.length ? this.markers[index].start : this.text.length;
    return Math.min(marker, this.nextOf('\n', from));
  }

  /** The end of `\([^()\n]*(?:\([^()\n]*\)[^()\n]*)*\)` from the `(` at `at`, or -1. */
  private srcEnd(at: number): number {
    const known = this.srcEnds.get(at);
    if (known !== undefined) return known;
    let end = -1;
    let inGroup = false;
    let from = at + 1;
    for (;;) {
      const stop = Math.min(this.nextOf('(', from), this.nextOf(')', from), this.nextOf('\n', from));
      if (stop >= this.text.length || this.text[stop] === '\n') break;
      if (this.text[stop] === ')') {
        if (!inGroup) {
          end = stop + 1;
          break;
        }
        inGroup = false;
      } else {
        if (inGroup) break;
        inGroup = true;
      }
      from = stop + 1;
    }
    this.srcEnds.set(at, end);
    return end;
  }

  /** The end of the image at `at` (a `!`), or -1. */
  private imageEnd(at: number): number {
    const text = this.text;
    if (text[at + 1] !== '[') return -1;
    // `[^\]\n]*` from at + 2 stops at the first `]` or newline; both alternatives meet the same one.
    const bracket = Math.min(this.nextOf(']', at + 2), this.nextOf('\n', at + 2));
    if (text[bracket] !== ']') return -1;
    if (text[bracket + 1] === '(') {
      const end = this.srcEnd(bracket + 1);
      if (end >= 0) return end;
    }
    if (text[at + 2] === '[' && bracket > at + 3 && text[bracket + 1] === ']') return bracket + 2;
    return -1;
  }

  matchAt(open: CommentMarkerAt): { image: number; imageEnd: number; post: number; end: number; close?: CommentMarkerAt } | null {
    const stop = this.stopFrom(open.end);
    for (let image = this.nextOf('!', open.end); image < stop; image = this.nextOf('!', image + 1)) {
      const imageEnd = this.imageEnd(image);
      if (imageEnd < 0) continue;
      const post = this.stopFrom(imageEnd);
      const index = this.markerFrom(post);
      const marker = index < this.markers.length && this.markers[index].start === post ? this.markers[index] : null;
      if (!marker) continue;
      if (marker.kind === 'close' || marker.kind === 'legacy-close') return { image, imageEnd, post, end: marker.end, close: marker };
      return { image, imageEnd, post, end: post };
    }
    return null;
  }
}
